import React from 'react';
import { Modal, Grid } from '@mantine/core';
import { Store } from '../context/SearchContext';
import CompanyAnalysisComponent from './CompanyAnalysisComponent';
import EmailGenerationComponent from './EmailGenerationComponent';

interface CombinedAnalysisModalProps {
  show: boolean;
  store: Store | null;
  onClose: () => void;
}

const CombinedAnalysisModal: React.FC<CombinedAnalysisModalProps> = ({
  show,
  store,
  onClose
}) => {
  const [analysisData, setAnalysisData] = React.useState<any>(null);

  const handleAnalysisDataUpdate = (data: any) => {
    setAnalysisData(data);
  };

  return (
    <Modal
      opened={show && !!store}
      onClose={onClose}
      title={`Analysis & Email for ${store?.name || ''}`}
      size="95vw"
      styles={{
        root: {
          zIndex: 1000
        },
        inner: {
          padding: '2rem'
        },
        content: {
          height: '90vh',
          maxWidth: 'none'
        }
      }}
    >
      {store && (
        <Grid h="100%">
          <Grid.Col span={6} style={{ borderRight: '1px solid var(--mantine-color-gray-3)', paddingRight: '1rem' }}>
            <CompanyAnalysisComponent 
              store={store} 
              onAnalysisDataUpdate={handleAnalysisDataUpdate}
            />
          </Grid.Col>
          <Grid.Col span={6} style={{ paddingLeft: '1rem' }}>
            <EmailGenerationComponent 
              store={store} 
              analysisData={analysisData}
            />
          </Grid.Col>
        </Grid>
      )}
    </Modal>
  );
};

export default CombinedAnalysisModal;