import React, { useState, useEffect } from 'react';
import { 
  Container, 
  Title, 
  Text, 
  TextInput, 
  Button, 
  Group, 
  Table, 
  Progress, 
  Alert, 
  Modal, 
  Badge, 
  Switch, 
  Anchor,
  Stack,
  Box
} from '@mantine/core';
import { useSearchContext, Store } from '../context/SearchContext';
import CombinedAnalysisModal from '../components/CombinedAnalysisModal';

const SearchPage: React.FC = () => {
  const [location, setLocation] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [results, setResults] = useState<Store[]>([]);
  const { setSearchResults, searchResults, useLocalAPI, setUseLocalAPI, getAPIEndpoint } = useSearchContext();
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [iframeError, setIframeError] = useState(false);
  const [loadingProgress, setLoadingProgress] = useState<{found: number, total?: number}>({found: 0});
  const [combinedModal, setCombinedModal] = useState<{show: boolean, store: Store | null}>({show: false, store: null});


  useEffect(() => {
    if (iframeError && previewUrl) {
      window.open(previewUrl, '_blank', 'noopener,noreferrer');
      setPreviewUrl(null);
      setIframeError(false);
    }
  }, [iframeError, previewUrl]);

  // Load previous search results on page load
  useEffect(() => {
    if (searchResults && searchResults.stores.length > 0) {
      setLocation(searchResults.location);
      setResults(searchResults.stores);
    }
  }, [searchResults]);

  const handleSearch = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    setResults([]);
    setLoadingProgress({found: 0});
    
    try {
      const response = await fetch(
        `${getAPIEndpoint()}/search/stream?location=${encodeURIComponent(location)}`,
        {
          method: 'GET',
          redirect: 'follow'
        }
      );
      
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const reader = response.body?.getReader();
      if (!reader) {
        throw new Error('Response body is not readable');
      }

      const decoder = new TextDecoder();
      let buffer = '';
      let searchLocation = location;
      let allStores: Store[] = [];

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || ''; // Keep incomplete line in buffer

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            try {
              const data = JSON.parse(line.slice(6));
              
              if (data.error) {
                setError(data.error);
                setLoading(false);
                return;
              }

              if (data.location && data.total_found !== undefined) {
                // Initial response with location info
                searchLocation = data.location;
                setLoadingProgress({found: 0, total: data.total_found});
                console.log(`Starting stream search for "${searchLocation}", expecting ${data.total_found} stores`);
              }

              if (data.store) {
                // New store received
                const store: Store = data.store;
                allStores.push(store);
                setResults(prev => [...prev, store]);
                setLoadingProgress(prev => ({...prev, found: allStores.length}));
                console.log(`Received store ${data.index}/${data.total}: ${store.name}`);
              }

              if (data.completed) {
                // Search completed
                console.log(`Search completed with ${allStores.length} stores`);
                const searchData = {
                  location: searchLocation,
                  stores: allStores,
                  timestamp: Date.now()
                };
                setSearchResults(searchData);
                setLoading(false);
              }
            } catch (parseErr) {
              console.error('Error parsing streaming data:', parseErr, 'Line:', line);
            }
          }
        }
      }
    } catch (err: any) {
      console.error('Streaming search error:', err);
      setError(err.message || 'An error occurred during streaming search');
      setLoading(false);
    }
  };

  const handleWebsiteClick = (url: string, e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();
    setPreviewUrl(url);
    setIframeError(false);
  };

  const handleClosePreview = () => {
    setPreviewUrl(null);
    setIframeError(false);
  };

  const handleAnalyzeCompany = (store: Store) => {
    setCombinedModal({show: true, store});
  };

  const handleCloseCombinedModal = () => {
    setCombinedModal({show: false, store: null});
  };

  const handleGenerateColdEmail = (store: Store) => {
    const subject = `Partnership Opportunity with ${store.name}`;
    const body = `Dear ${store.name} Team,

I hope this email finds you well. I'm reaching out to explore potential partnership opportunities with your hardware store.

Store Details:
- Name: ${store.name}
- Address: ${store.address}
${store.phone ? `- Phone: ${store.phone}` : ''}
${store.website ? `- Website: ${store.website}` : ''}

I believe there could be mutual benefits in working together. Would you be interested in discussing this further?

Best regards,
[Your Name]
[Your Contact Information]`;

    const mailtoLink = `mailto:${store.email || ''}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
    window.open(mailtoLink, '_blank');
  };

  return (
    <>
      {/* API Endpoint Toggle - Fixed Position */}
      <Box 
        bg="white"
        p="xs"
        style={{
          position: 'fixed', 
          top: '80px', 
          right: '20px', 
          zIndex: 1000,
          borderRadius: '8px',
          boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
          border: '1px solid var(--mantine-color-gray-3)'
        }}
      >
        <Group gap="xs" align="center">
          <Text size="xs" c="dimmed">API:</Text>
          <Badge 
            variant={!useLocalAPI ? 'filled' : 'light'}
            size="xs"
            style={{cursor: 'pointer'}}
            onClick={() => setUseLocalAPI(false)}
            title="Use Production API (Railway)"
          >
            🌐 Prod
          </Badge>
          <Badge 
            variant={useLocalAPI ? 'filled' : 'light'}
            size="xs"
            style={{cursor: 'pointer'}}
            onClick={() => setUseLocalAPI(true)}
            title="Use Local API (localhost:8002)"
          >
            💻 Local
          </Badge>
        </Group>
      </Box>

      <Container size="xl" py="xl">
      
      <Stack align="center" gap="md" mb="xl">
        <Title 
          order={1} 
          size="h1" 
          ta="center"
          style={{
            background: 'linear-gradient(45deg, orange, gold)',
            WebkitBackgroundClip: 'text',
            WebkitTextFillColor: 'transparent',
            backgroundClip: 'text'
          }}
        >
          Hardware Store Finder
        </Title>
        <Text size="lg" c="dimmed" ta="center" fs="italic">
          Find hardware stores near you with ease
        </Text>
      </Stack>
      
      <Stack align="center" gap="sm" mb="xl">
        <Title order={2} size="h3" ta="center">Search for Hardware Stores</Title>
        <Text c="dimmed" ta="center">
          Enter a location to search for hardware stores in that area
        </Text>
      </Stack>
      
      <form onSubmit={handleSearch}>
        <Group justify="center" gap="md" mb="xl">
          <TextInput
            value={location}
            onChange={e => setLocation(e.currentTarget.value)}
            placeholder="Enter a location (city, address, etc.)"
            required
            style={{ width: 300 }}
          />
          <Button
            type="submit"
            loading={loading}
            disabled={loading}
          >
            {loading ? (
              loadingProgress.total 
                ? `Found ${loadingProgress.found}/${loadingProgress.total} stores...` 
                : 'Searching...'
            ) : 'Search'}
          </Button>
        </Group>
      </form>


      {loading && loadingProgress.total && (
        <Stack align="center" gap="sm" mb="xl">
          <Progress 
            value={(loadingProgress.found / loadingProgress.total) * 100}
            size="lg"
            style={{ width: 300 }}
          />
          <Text size="sm" c="dimmed" fs="italic">
            Loading stores: {loadingProgress.found} of {loadingProgress.total}
          </Text>
        </Stack>
      )}

      {error && (
        <Alert color="red" mb="xl">
          {error}
        </Alert>
      )}

      {/* Search Results Table */}
      {results.length > 0 && (
        <Stack gap="md" mb="xl">
          <Title order={3} ta="center">Found {results.length} Hardware Store{results.length !== 1 ? 's' : ''} near "{location}"</Title>
          <Table striped highlightOnHover withTableBorder>
            <Table.Thead>
              <Table.Tr>
                <Table.Th>Name</Table.Th>
                <Table.Th>Address</Table.Th>
                <Table.Th>Phone</Table.Th>
                <Table.Th>Website</Table.Th>
                <Table.Th>Analyze</Table.Th>
              </Table.Tr>
            </Table.Thead>
            <Table.Tbody>
              {results.map((store: Store, idx: number) => (
                <Table.Tr key={idx}>
                  <Table.Td fw={500}>{store.name}</Table.Td>
                  <Table.Td>{store.address}</Table.Td>
                  <Table.Td>
                    {store.phone ? (
                      <Anchor href={`tel:${store.phone}`} c="blue">
                        {store.phone}
                      </Anchor>
                    ) : ''}
                  </Table.Td>
                  <Table.Td>
                    {store.website && (
                      <Button
                        variant="light"
                        size="xs"
                        component="a"
                        href={store.website}
                        target="_blank"
                        rel="noopener noreferrer"
                        onClick={e => store.website && handleWebsiteClick(store.website, e as any)}
                      >
                        Visit Website
                      </Button>
                    )}
                  </Table.Td>
                  <Table.Td>
                    <Button
                      variant="filled"
                      size="xs"
                      onClick={() => handleAnalyzeCompany(store)}
                      title="Analyze company information"
                    >
                      AI Analyze
                    </Button>
                  </Table.Td>
                </Table.Tr>
              ))}
            </Table.Tbody>
          </Table>
        </Stack>
      )}

      {/* Website Preview Modal */}
      <Modal
        opened={!!previewUrl}
        onClose={handleClosePreview}
        title="Website Preview"
        size="xl"
        centered
      >
        <Stack gap="md">
          <Group justify="flex-end">
            <Button
              variant="light"
              onClick={() => {
                if (previewUrl) {
                  window.open(previewUrl, '_blank', 'noopener,noreferrer');
                  handleClosePreview();
                }
              }}
            >
              Open in new tab
            </Button>
          </Group>
          {previewUrl && (
            <iframe
              src={previewUrl}
              title="Website Preview"
              style={{ width: '100%', height: '70vh', border: 'none' }}
              onError={() => setIframeError(true)}
            />
          )}
        </Stack>
      </Modal>

      {/* Combined Analysis & Email Modal */}
      <CombinedAnalysisModal
        show={combinedModal.show}
        store={combinedModal.store}
        onClose={handleCloseCombinedModal}
      />

      {results.length === 0 && !loading && !error && (
        <Stack align="center" gap="md" mt="xl">
          <Title order={3}>How it works:</Title>
          <Stack gap="xs" style={{ maxWidth: 500, textAlign: 'left' }}>
            <Text>1. Enter your location (city, address, or landmark)</Text>
            <Text>2. Click search to find nearby hardware stores</Text>
            <Text>3. Browse results with contact information</Text>
            <Text>4. Visit store websites directly from the results</Text>
          </Stack>
        </Stack>
      )}
      </Container>
    </>
  );
};

export default SearchPage;