import React from 'react';
import ReactMarkdown from 'react-markdown';
import remarkGfm from 'remark-gfm';
import { 
  Title, 
  Text, 
  Button, 
  Group, 
  Stack, 
  Alert, 
  Loader, 
  Badge, 
  List,
  Card,
  Anchor,
  Box,
  Divider
} from '@mantine/core';
import { Store, useSearchContext } from '../context/SearchContext';

// Fallback company analysis template - used when AI analysis is not available
const FALLBACK_ANALYSIS_TEMPLATE = {
  analysisPoints: [
    'Location-based market analysis',
    'Potential partnership opportunities', 
    'Business size estimation',
    'Contact strategy recommendations'
  ],
  nextSteps: [
    'Research company background',
    'Analyze local market presence',
    'Identify decision makers',
    'Prepare partnership proposal'
  ]
};

interface CompanyAnalysisComponentProps {
  store: Store;
  onAnalysisDataUpdate: (data: any) => void;
}

// localStorage functions for saving/loading analysis data
const getStorageKey = (store: Store) => `analysis_${store.name}_${store.address}`;

const saveAnalysisToStorage = (store: Store, analysisData: any, hasAI: boolean = false) => {
  try {
    const key = getStorageKey(store);
    const dataToSave = {
      ...analysisData,
      hasAIAnalysis: hasAI,
      timestamp: new Date().toISOString()
    };
    localStorage.setItem(key, JSON.stringify(dataToSave));
  } catch (error) {
    console.error('Error saving analysis to localStorage:', error);
  }
};

const loadAnalysisFromStorage = (store: Store) => {
  try {
    const key = getStorageKey(store);
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : null;
  } catch (error) {
    console.error('Error loading analysis from localStorage:', error);
    return null;
  }
};

const CompanyAnalysisComponent: React.FC<CompanyAnalysisComponentProps> = ({
  store,
  onAnalysisDataUpdate
}) => {
  const [analysisData, setAnalysisData] = React.useState<any>(null);
  const [loadingAnalysis, setLoadingAnalysis] = React.useState(false);
  const [analysisError, setAnalysisError] = React.useState<string | null>(null);
  const [hasAIAnalysis, setHasAIAnalysis] = React.useState(false);
  const [language, setLanguage] = React.useState<'english' | 'chinese'>('english');
  const [chineseAnalysis, setChineseAnalysis] = React.useState<string | null>(null);
  const [loadingChinese, setLoadingChinese] = React.useState(false);
  const { getAPIEndpoint } = useSearchContext();

  // API call for company analysis with streaming
  const fetchCompanyAnalysis = React.useCallback(async () => {
    if (!store) return;
    
    setLoadingAnalysis(true);
    setAnalysisError(null);
    
    try {
      const response = await fetch(
        `${getAPIEndpoint()}/api/analyze-company/stream`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            name: store.name,
            address: store.address,
            phone: store.phone,
            website: store.website,
            language: language
          })
        }
      );

      if (!response.ok) {
        throw new Error('Backend endpoint not available');
      }

      // Initialize analysis data with basic info
      const initialData = {
        basicInfo: {
          name: store.name,
          address: store.address,
          phone: store.phone,
          website: store.website
        },
        perplexityAnalysis: '',
        analysisPoints: [],
        nextSteps: [],
        productCategories: []
      };
      setAnalysisData(initialData);
      setHasAIAnalysis(true);

      // Handle streaming response
      const reader = response.body?.getReader();
      const decoder = new TextDecoder();
      let streamedContent = '';

      if (reader) {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          const chunk = decoder.decode(value);
          const lines = chunk.split('\n');

          for (const line of lines) {
            if (line.startsWith('data: ')) {
              try {
                const data = JSON.parse(line.substring(6));
                
                if (data.error) {
                  console.error('Streaming error:', data.error);
                  setAnalysisError(data.error);
                  break;
                }
                
                if (data.type === 'content') {
                  streamedContent += data.content;
                  // Update the analysis data with streaming content
                  const updatedData = {
                    ...initialData,
                    perplexityAnalysis: streamedContent
                  };
                  setAnalysisData(updatedData);
                  onAnalysisDataUpdate(updatedData);
                } else if (data.type === 'complete') {
                  // Final complete data
                  setAnalysisData(data.data);
                  onAnalysisDataUpdate(data.data);
                  saveAnalysisToStorage(store, data.data, true);
                } else if (data.status) {
                  // Status updates (optional: could show these to user)
                  console.log('Analysis status:', data.message);
                }
              } catch (e) {
                // Ignore malformed JSON lines
                console.warn('Failed to parse streaming data:', line);
              }
            }
          }
        }
      }
    } catch (error) {
      console.log('Using fallback analysis data');
      // Fallback to default analysis when backend is not ready
      const fallbackData = {
        basicInfo: {
          name: store.name,
          address: store.address,
          phone: store.phone,
          website: store.website
        },
        perplexityAnalysis: null
      };
      setAnalysisData(fallbackData);
      onAnalysisDataUpdate(fallbackData);
      setHasAIAnalysis(false);
      saveAnalysisToStorage(store, fallbackData, false);
    } finally {
      setLoadingAnalysis(false);
    }
  }, [store, language, onAnalysisDataUpdate, getAPIEndpoint]);

  // API call for Chinese company analysis with streaming
  const fetchChineseAnalysis = React.useCallback(async () => {
    if (!store) return;
    
    setLoadingChinese(true);
    setChineseAnalysis('');
    
    try {
      const response = await fetch(
        `${getAPIEndpoint()}/api/analyze-company/stream`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
          },
          body: JSON.stringify({
            name: store.name,
            address: store.address,
            phone: store.phone,
            website: store.website,
            language: 'chinese'
          })
        }
      );

      if (!response.ok) {
        throw new Error('Backend endpoint not available');
      }

      // Handle streaming response
      const reader = response.body?.getReader();
      const decoder = new TextDecoder();
      let streamedContent = '';

      if (reader) {
        while (true) {
          const { done, value } = await reader.read();
          if (done) break;

          const chunk = decoder.decode(value);
          const lines = chunk.split('\n');

          for (const line of lines) {
            if (line.startsWith('data: ')) {
              try {
                const data = JSON.parse(line.substring(6));
                
                if (data.error) {
                  console.error('Chinese streaming error:', data.error);
                  setChineseAnalysis('Chinese analysis not available. Please try again later.');
                  break;
                }
                
                if (data.type === 'content') {
                  streamedContent += data.content;
                  setChineseAnalysis(streamedContent);
                } else if (data.type === 'complete') {
                  // Final complete data
                  setChineseAnalysis(data.data.perplexityAnalysis);
                  // Save Chinese analysis to localStorage
                  if (store) {
                    const storageKey = `${getStorageKey(store)}_chinese`;
                    localStorage.setItem(storageKey, JSON.stringify({
                      analysis: data.data.perplexityAnalysis,
                      timestamp: new Date().toISOString()
                    }));
                  }
                } else if (data.status) {
                  console.log('Chinese analysis status:', data.message);
                }
              } catch (e) {
                console.warn('Failed to parse Chinese streaming data:', line);
              }
            }
          }
        }
      }
    } catch (error) {
      console.log('Chinese analysis failed:', error);
      setChineseAnalysis('Chinese analysis not available. Please try again later.');
    } finally {
      setLoadingChinese(false);
    }
  }, [store, getAPIEndpoint]);

  // Handle language switching
  const handleLanguageSwitch = (newLang: 'english' | 'chinese') => {
    setLanguage(newLang);
    if (newLang === 'chinese' && !chineseAnalysis && hasAIAnalysis) {
      // Check localStorage for Chinese analysis first
      if (store) {
        const storageKey = `${getStorageKey(store)}_chinese`;
        const cached = localStorage.getItem(storageKey);
        if (cached) {
          const parsedCache = JSON.parse(cached);
          setChineseAnalysis(parsedCache.analysis);
        } else {
          fetchChineseAnalysis();
        }
      }
    }
  };

  // Load company analysis when component mounts
  React.useEffect(() => {
    if (store) {
      // First check localStorage for cached analysis
      const cachedAnalysis = loadAnalysisFromStorage(store);
      if (cachedAnalysis) {
        setAnalysisData(cachedAnalysis);
        onAnalysisDataUpdate(cachedAnalysis);
        setHasAIAnalysis(cachedAnalysis.hasAIAnalysis || false);
        
        // Load Chinese analysis if available
        const chineseStorageKey = `${getStorageKey(store)}_chinese`;
        const cachedChinese = localStorage.getItem(chineseStorageKey);
        if (cachedChinese) {
          const parsedChinese = JSON.parse(cachedChinese);
          setChineseAnalysis(parsedChinese.analysis);
        }
      } else {
        // Set up basic info without making API call
        const basicData = {
          basicInfo: {
            name: store.name,
            address: store.address,
            phone: store.phone,
            website: store.website
          },
          perplexityAnalysis: null
        };
        setAnalysisData(basicData);
        onAnalysisDataUpdate(basicData);
        setHasAIAnalysis(false);
      }
    }
  }, [store]); // Removed onAnalysisDataUpdate to prevent loops

  return (
    <Stack h="100%" style={{ overflow: 'hidden' }}>
      {/* Fixed Header Section */}
      <Box style={{ flexShrink: 0, padding: '0 0 16px 0', borderBottom: '1px solid var(--mantine-color-gray-3)' }}>
        <Group justify="space-between" align="center">
          <Stack gap={2}>
            <Text size="sm" c="dimmed">Company Analysis</Text>
            <Title order={2}>{store.name}</Title>
          </Stack>
          {hasAIAnalysis && (
            <Group gap="xs">
              <Button
                size="xs"
                variant={language === 'english' ? 'filled' : 'light'}
                onClick={() => handleLanguageSwitch('english')}
              >
                English
              </Button>
              <Button
                size="xs"
                variant={language === 'chinese' ? 'filled' : 'light'}
                onClick={() => handleLanguageSwitch('chinese')}
                disabled={loadingChinese}
              >
                {loadingChinese ? '📡' : '中文'}
              </Button>
            </Group>
          )}
        </Group>
      </Box>
      
      {/* Scrollable Content Area */}
      <Box style={{ flex: 1, overflow: 'auto', paddingRight: '8px' }}>
        <Stack gap="lg" p="md">
        {loadingAnalysis ? (
          <Stack align="center" gap="md" style={{ flexShrink: 0 }}>
            <Group gap="sm">
              <Loader size="sm" />
              <Text>Analyzing company information...</Text>
            </Group>
          </Stack>
        ) : null}

        {analysisData && (
          <>
            {/* Basic Information Card - Fixed height */}
            <Card shadow="sm" p="md" radius="md" style={{ flexShrink: 0 }}>
              <Title order={3} mb="md">Basic Information</Title>
              <List spacing="xs">
                <List.Item><Text component="span" fw={500}>Name:</Text> {analysisData.basicInfo?.name || store.name}</List.Item>
                <List.Item><Text component="span" fw={500}>Address:</Text> {analysisData.basicInfo?.address || store.address}</List.Item>
                {(analysisData.basicInfo?.phone || store.phone) && (
                  <List.Item><Text component="span" fw={500}>Phone:</Text> {analysisData.basicInfo?.phone || store.phone}</List.Item>
                )}
                {(analysisData.basicInfo?.website || store.website) && (
                  <List.Item>
                    <Text component="span" fw={500}>Website:</Text>{' '}
                    <Anchor 
                      href={analysisData.basicInfo?.website || store.website} 
                      target="_blank" 
                      rel="noopener noreferrer"
                    >
                      {analysisData.basicInfo?.website || store.website}
                    </Anchor>
                  </List.Item>
                )}
              </List>
            </Card>

            {/* AI Analysis Card - Flexible height */}
            {hasAIAnalysis && (analysisData.perplexityAnalysis || chineseAnalysis || loadingAnalysis) ? (
              <Card shadow="sm" p="md" radius="md" style={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
                <Group justify="space-between" align="center" mb="md" style={{ flexShrink: 0 }}>
                  <Title order={3}>
                    {language === 'chinese' ? 'AI 市场分析' : 'AI Market Analysis'}
                  </Title>
                  {loadingChinese && language === 'chinese' && (
                    <Badge variant="light" size="sm">
                      ✨ Streaming...
                    </Badge>
                  )}
                </Group>
                
                {/* Streaming content during loading */}
                {loadingAnalysis && analysisData?.perplexityAnalysis && (
                  <Box 
                    className="company-analysis-streaming-display"
                    style={{ 
                      flex: 1,
                      overflow: 'auto',
                      paddingRight: '8px',
                      border: '1px solid var(--mantine-color-gray-3)',
                      borderRadius: '4px',
                      padding: '12px',
                      backgroundColor: 'var(--mantine-color-gray-0)'
                    }}
                  >
                    <Text size="sm" c="dimmed" mb="xs">
                      ✨ Streaming analysis results...
                    </Text>
                    <Text size="sm" style={{ lineHeight: 1.6 }}>
                      {analysisData.perplexityAnalysis}
                      <span className="streaming-cursor">|</span>
                    </Text>
                  </Box>
                )}
                
                {/* Final analysis content */}
                {!loadingAnalysis && (analysisData.perplexityAnalysis || chineseAnalysis) && (
                  <Box 
                    className="company-analysis-response-display"
                    style={{ 
                      flex: 1,
                      overflow: 'auto',
                      paddingRight: '8px',
                      lineHeight: 1.6
                    }}
                  >
                    <ReactMarkdown
                        remarkPlugins={[remarkGfm]}
                        components={{
                          p: ({ children }) => <p style={{ marginBottom: '12px', lineHeight: '1.6' }}>{children}</p>,
                          ul: ({ children }) => <ul style={{ marginBottom: '12px', paddingLeft: '20px' }}>{children}</ul>,
                          ol: ({ children }) => <ol style={{ marginBottom: '12px', paddingLeft: '20px' }}>{children}</ol>,
                          li: ({ children }) => <li style={{ marginBottom: '4px' }}>{children}</li>,
                          h1: ({ children }) => <h1 style={{ marginBottom: '12px', marginTop: '20px', fontSize: '1.5em', fontWeight: 'bold' }}>{children}</h1>,
                          h2: ({ children }) => <h2 style={{ marginBottom: '10px', marginTop: '18px', fontSize: '1.3em', fontWeight: 'bold' }}>{children}</h2>,
                          h3: ({ children }) => <h3 style={{ marginBottom: '8px', marginTop: '16px', fontSize: '1.2em', fontWeight: 'bold' }}>{children}</h3>,
                          h4: ({ children }) => <h4 style={{ marginBottom: '6px', marginTop: '14px', fontSize: '1.1em', fontWeight: 'bold' }}>{children}</h4>,
                          table: ({ children }) => (
                            <table style={{ 
                              width: '100%', 
                              borderCollapse: 'collapse', 
                              marginBottom: '16px',
                              border: '1px solid var(--mantine-color-gray-3)',
                              fontSize: '0.9em'
                            }}>
                              {children}
                            </table>
                          ),
                          thead: ({ children }) => (
                            <thead style={{ backgroundColor: 'var(--mantine-color-gray-1)' }}>
                              {children}
                            </thead>
                          ),
                          th: ({ children }) => (
                            <th style={{ 
                              padding: '8px 12px', 
                              border: '1px solid var(--mantine-color-gray-3)',
                              fontWeight: 'bold',
                              textAlign: 'left'
                            }}>
                              {children}
                            </th>
                          ),
                          td: ({ children }) => (
                            <td style={{ 
                              padding: '8px 12px', 
                              border: '1px solid var(--mantine-color-gray-3)'
                            }}>
                              {children}
                            </td>
                          ),
                          a: ({ children, href }) => (
                            <a 
                              href={href} 
                              target="_blank" 
                              rel="noopener noreferrer"
                              style={{ 
                                color: 'var(--mantine-color-blue-6)', 
                                textDecoration: 'none',
                                fontWeight: 'bold'
                              }}
                            >
                              {children}
                            </a>
                          )
                        }}
                      >
                      {language === 'chinese' && chineseAnalysis 
                        ? chineseAnalysis + (loadingChinese ? ' ▋' : '')
                        : analysisData.perplexityAnalysis + (loadingAnalysis && analysisData.perplexityAnalysis ? ' ▋' : '')
                      }
                    </ReactMarkdown>
                  </Box>
                )}
              </Card>
            ) : (
              !hasAIAnalysis && (
                <Stack gap="md" style={{ flexShrink: 0 }}>
                  <Card shadow="sm" p="md" radius="md">
                    <Title order={3} mb="md">Analysis Points</Title>
                    <List spacing="xs">
                      {FALLBACK_ANALYSIS_TEMPLATE.analysisPoints.map((point: string, idx: number) => (
                        <List.Item key={idx}>{point}</List.Item>
                      ))}
                    </List>
                  </Card>

                  <Card shadow="sm" p="md" radius="md">
                    <Title order={3} mb="md">Next Steps</Title>
                    <List type="ordered" spacing="xs">
                      {FALLBACK_ANALYSIS_TEMPLATE.nextSteps.map((step: string, idx: number) => (
                        <List.Item key={idx}>{step}</List.Item>
                      ))}
                    </List>
                  </Card>
                </Stack>
              )
            )}
          </>
        )}

          {!analysisData && !loadingAnalysis && (
            <Alert color="red" title="Error">
              <Text>Unable to load company analysis.</Text>
            </Alert>
          )}
        </Stack>
      </Box>

      {/* Fixed Footer Area */}
      <Box style={{ flexShrink: 0, padding: '16px 0 0 0', borderTop: '1px solid var(--mantine-color-gray-3)' }}>
        <Stack align="center" gap="md" py="md">
          <Text fs="italic" c="dimmed">
            This analysis can help inform your outreach strategy.
          </Text>
          <Group justify="center" gap="md">
            {!hasAIAnalysis && (
              <Button
                variant="filled"
                onClick={fetchCompanyAnalysis}
                disabled={loadingAnalysis}
                loading={loadingAnalysis}
              >
                {loadingAnalysis ? 'Analyzing...' : 'Start AI Analysis'}
              </Button>
            )}
            {hasAIAnalysis && (
              <Button
                variant="light"
                onClick={() => {
                  setAnalysisData(null);
                  setHasAIAnalysis(false);
                  setChineseAnalysis(null);
                  setLanguage('english');
                  fetchCompanyAnalysis();
                }}
                disabled={loadingAnalysis}
                loading={loadingAnalysis}
              >
                {loadingAnalysis ? 'Refreshing...' : 'Refresh Analysis'}
              </Button>
            )}
          </Group>
        </Stack>
      </Box>
    </Stack>
  );
};

export default CompanyAnalysisComponent;