import React, { useState, useEffect, useMemo } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { Container, Title, Text, Table, Modal, Button, Group, Stack, Anchor } from '@mantine/core';
import { useSearchContext, Store } from '../context/SearchContext';

const ResultsPage: React.FC = () => {
  const navigate = useNavigate();
  const { searchResults } = useSearchContext();
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [iframeError, setIframeError] = useState<boolean>(false);

  const results = useMemo(() => searchResults?.stores || [], [searchResults?.stores]);
  const searchLocation = useMemo(() => searchResults?.location || '', [searchResults?.location]);

  useEffect(() => {
    if (!searchResults || !results.length) {
      navigate('/');
    }
  }, [searchResults, results, navigate]);

  useEffect(() => {
    if (iframeError && previewUrl) {
      window.open(previewUrl, '_blank', 'noopener,noreferrer');
      setPreviewUrl(null);
      setIframeError(false);
    }
  }, [iframeError, previewUrl]);

  const handleWebsiteClick = (url: string, e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault();
    setPreviewUrl(url);
    setIframeError(false);
  };

  const handleClosePreview = () => {
    setPreviewUrl(null);
    setIframeError(false);
  };

  if (!results.length) {
    return (
      <Container size="md" py="xl">
        <Stack align="center" gap="md">
          <Title order={2}>No Results Found</Title>
          <Text c="dimmed">No search results to display.</Text>
          <Button component={Link} to="/" variant="light">
            ← Back to Search
          </Button>
        </Stack>
      </Container>
    );
  }

  return (
    <Container size="xl" py="xl">
      <Stack gap="lg">
        <Stack align="center" gap="xs">
          <Title order={2}>Hardware Stores near "{searchLocation}"</Title>
          <Text c="dimmed">Found {results.length} store{results.length !== 1 ? 's' : ''}</Text>
          <Button component={Link} to="/" variant="light" size="sm">
            ← Search Again
          </Button>
        </Stack>

        <Table striped highlightOnHover withTableBorder>
          <Table.Thead>
            <Table.Tr>
              <Table.Th>Name</Table.Th>
              <Table.Th>Address</Table.Th>
              <Table.Th>Phone</Table.Th>
              <Table.Th>Website</Table.Th>
            </Table.Tr>
          </Table.Thead>
          <Table.Tbody>
            {results.map((store: Store, idx: number) => (
              <Table.Tr key={idx}>
                <Table.Td fw={500}>{store.name}</Table.Td>
                <Table.Td>{store.address}</Table.Td>
                <Table.Td>
                  {store.phone ? (
                    <Anchor href={`tel:${store.phone}`} c="blue">
                      {store.phone}
                    </Anchor>
                  ) : ''}
                </Table.Td>
                <Table.Td>
                  {store.website && (
                    <Button
                      variant="light"
                      size="xs"
                      component="a"
                      href={store.website}
                      target="_blank"
                      rel="noopener noreferrer"
                      onClick={e => store.website && handleWebsiteClick(store.website, e as any)}
                    >
                      Visit Website
                    </Button>
                  )}
                </Table.Td>
              </Table.Tr>
            ))}
          </Table.Tbody>
        </Table>
      </Stack>

      {/* Website Preview Modal */}
      <Modal
        opened={!!previewUrl}
        onClose={handleClosePreview}
        title="Website Preview"
        size="xl"
        centered
      >
        <Stack gap="md">
          <Group justify="flex-end">
            <Button
              variant="light"
              onClick={() => {
                if (previewUrl) {
                  window.open(previewUrl, '_blank', 'noopener,noreferrer');
                  handleClosePreview();
                }
              }}
            >
              Open in new tab
            </Button>
          </Group>
          {previewUrl && (
            <iframe
              src={previewUrl}
              title="Website Preview"
              style={{ width: '100%', height: '70vh', border: 'none' }}
              onError={() => setIframeError(true)}
            />
          )}
        </Stack>
      </Modal>
    </Container>
  );
};

export default ResultsPage;